insert into public.angelcare_marketplace_footer_profiles(profile_key,name,description,theme_id,status,is_default,locale_strategy,settings,brand,authority_statement,version_number,published_at) select 'global-marketplace','{"fr":"Footer global Marketplace","en":"Global Marketplace footer","ar":"تذييل السوق العالمي"}'::jsonb,'{"fr":"Profil public global ANGELCARE.","en":"ANGELCARE global public profile.","ar":"ملف أنجل كير العام."}'::jsonb,t.id,'published',true,'shared','{"desktop_columns":4,"tablet_columns":2,"mobile_accordion":"multiple","show_service_bar":true,"show_quick_links":true}'::jsonb,'{"eyebrow":{"fr":"ANGELCARE GLOBAL MARKETPLACE","en":"ANGELCARE GLOBAL MARKETPLACE","ar":"سوق أنجل كير العالمي"},"title":{"fr":"Une infrastructure de confiance pour chaque parcours.","en":"A trusted infrastructure for every journey.","ar":"بنية موثوقة لكل رحلة وخدمة."},"description":{"fr":"Familles, établissements, professionnels et partenaires disposent d’un accès direct aux équipes spécialisées qui opèrent le Marketplace ANGELCARE.","en":"Families, institutions, professionals and partners receive direct access to the specialist teams operating the ANGELCARE Marketplace.","ar":"تحصل الأسر والمؤسسات والمهنيون والشركاء على وصول مباشر إلى الفرق المتخصصة التي تدير سوق أنجل كير."}}'::jsonb,'Copyright ANGELCARE MARKETPLACE - DESIGNED - DEVELOPPED - OPERATED BY ANGELCARE FOR ANGELCARE ONLY.',1,now() from public.angelcare_marketplace_footer_themes t where t.theme_key='sovereign-navy-ice' on conflict(profile_key) do update set name=excluded.name,description=excluded.description,theme_id=excluded.theme_id,status='published',is_default=true,settings=excluded.settings,brand=excluded.brand,authority_statement=excluded.authority_statement,updated_at=now();
