    insert into public.angelcare_marketplace_footer_links(section_id,link_key,label,href,link_type,open_new_tab,rel,visibility,analytics_key,status,sort_order,updated_by)
insert into public.angelcare_marketplace_footer_publications(profile_id,version_id,action,affected_routes,actor_id,evidence) values(p_profile_id,p_version_id,'restore',array['/angelcare-marketplace/fr','/angelcare-marketplace/en','/angelcare-marketplace/ar'],p_actor_id,jsonb_build_object('restoredFrom',p_version_id,'dataPreserved',true));
insert into public.angelcare_marketplace_footer_profile_versions(profile_id,version_number,snapshot,change_summary) select p.id,1,public.angelcare_marketplace_footer_snapshot(p.id),'Initial premium enterprise footer profile' from public.angelcare_marketplace_footer_profiles p where p.profile_key='global-marketplace' on conflict(profile_id,version_number) do nothing;
