begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_footer_themes (id uuid primary key default gen_random_uuid(),theme_key text not null unique,name jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,layout_key text not null,tokens jsonb not null default '{}'::jsonb,preview_metadata jsonb not null default '{}'::jsonb,status text not null default 'active' check(status in ('active','draft','archived')),is_system boolean not null default false,sort_order integer not null default 10,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_profiles (id uuid primary key default gen_random_uuid(),profile_key text not null unique,name jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,theme_id uuid references public.angelcare_marketplace_footer_themes(id),parent_profile_id uuid references public.angelcare_marketplace_footer_profiles(id),status text not null default 'draft' check(status in ('draft','published','scheduled','suspended','archived')),is_default boolean not null default false,locale_strategy text not null default 'shared' check(locale_strategy in ('shared','locale_specific')),settings jsonb not null default '{}'::jsonb,brand jsonb not null default '{}'::jsonb,authority_statement text not null,version_number integer not null default 1,published_at timestamptz,scheduled_at timestamptz,expires_at timestamptz,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists angelcare_marketplace_footer_one_default_idx on public.angelcare_marketplace_footer_profiles((is_default)) where is_default=true;
create table if not exists public.angelcare_marketplace_footer_sections (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.angelcare_marketplace_footer_profiles(id) on delete cascade,section_key text not null,kind text not null default 'directory',title jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,eyebrow jsonb not null default '{}'::jsonb,icon_key text,settings jsonb not null default '{}'::jsonb,targeting jsonb not null default '{}'::jsonb,contact_desk_keys text[] not null default '{}',status text not null default 'active' check(status in ('active','hidden','archived')),sort_order integer not null default 10,column_span integer not null default 1 check(column_span between 1 and 6),mobile_default_open boolean not null default false,locked boolean not null default false,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(profile_id,section_key));
create table if not exists public.angelcare_marketplace_footer_links (id uuid primary key default gen_random_uuid(),section_id uuid not null references public.angelcare_marketplace_footer_sections(id) on delete cascade,link_key text not null,label jsonb not null default '{}'::jsonb,href text not null,link_type text not null default 'internal' check(link_type in ('internal','external','email','phone','document','action')),open_new_tab boolean not null default false,rel text[] not null default '{}',visibility jsonb not null default '{}'::jsonb,analytics_key text,status text not null default 'active' check(status in ('active','hidden','archived')),sort_order integer not null default 10,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(section_id,link_key));
create table if not exists public.angelcare_marketplace_footer_contact_desks (id uuid primary key default gen_random_uuid(),desk_key text not null unique,label jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,email text not null,phone text,languages text[] not null default '{fr,en,ar}',territories text[] not null default '{MA}',response_commitment jsonb not null default '{}'::jsonb,escalation_desk_key text,operating_hours jsonb not null default '{}'::jsonb,status text not null default 'active' check(status in ('active','suspended','archived')),sort_order integer not null default 10,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_targeting_rules (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.angelcare_marketplace_footer_profiles(id) on delete cascade,rule_key text not null unique,priority integer not null default 0,conditions jsonb not null default '{}'::jsonb,status text not null default 'active' check(status in ('active','paused','archived')),starts_at timestamptz,ends_at timestamptz,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_schedules (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.angelcare_marketplace_footer_profiles(id) on delete cascade,schedule_key text not null unique,action text not null check(action in ('publish','suspend','resume','expire')),execute_at timestamptz not null,timezone text not null default 'Africa/Casablanca',status text not null default 'scheduled' check(status in ('scheduled','executed','cancelled','failed')),execution_evidence jsonb not null default '{}'::jsonb,created_by text,updated_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_profile_versions (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.angelcare_marketplace_footer_profiles(id) on delete cascade,version_number integer not null,snapshot jsonb not null,change_summary text,created_by text,created_at timestamptz not null default now(),unique(profile_id,version_number));
create table if not exists public.angelcare_marketplace_footer_publications (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.angelcare_marketplace_footer_profiles(id),version_id uuid references public.angelcare_marketplace_footer_profile_versions(id),action text not null,affected_routes text[] not null default '{}',result text not null default 'success',evidence jsonb not null default '{}'::jsonb,actor_id text,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_analytics_events (id uuid primary key default gen_random_uuid(),profile_id uuid references public.angelcare_marketplace_footer_profiles(id),event_type text not null,action_key text,locale text not null default 'fr',pathname text not null default '/',device_class text not null default 'unknown',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists angelcare_marketplace_footer_events_profile_created_idx on public.angelcare_marketplace_footer_analytics_events(profile_id,created_at desc);
create table if not exists public.angelcare_marketplace_footer_audit_events (id uuid primary key default gen_random_uuid(),actor_id text,action text not null,object_type text not null,object_id text,before_value jsonb,after_value jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_capabilities (id uuid primary key default gen_random_uuid(),capability_key text not null unique,capability_group text not null,label text not null,status text not null default 'active',delivery_mode text not null default 'native',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_footer_component_definitions (id uuid primary key default gen_random_uuid(),component_key text not null unique,label jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,property_schema jsonb not null default '{}'::jsonb,allowed_child_types text[] not null default '{}',supports_targeting boolean not null default true,supports_localization boolean not null default true,supports_analytics boolean not null default true,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.angelcare_marketplace_footer_themes enable row level security;
alter table public.angelcare_marketplace_footer_profiles enable row level security;
alter table public.angelcare_marketplace_footer_sections enable row level security;
alter table public.angelcare_marketplace_footer_links enable row level security;
alter table public.angelcare_marketplace_footer_contact_desks enable row level security;
alter table public.angelcare_marketplace_footer_targeting_rules enable row level security;
alter table public.angelcare_marketplace_footer_schedules enable row level security;
alter table public.angelcare_marketplace_footer_profile_versions enable row level security;
alter table public.angelcare_marketplace_footer_publications enable row level security;
alter table public.angelcare_marketplace_footer_analytics_events enable row level security;
alter table public.angelcare_marketplace_footer_audit_events enable row level security;
alter table public.angelcare_marketplace_footer_capabilities enable row level security;
alter table public.angelcare_marketplace_footer_component_definitions enable row level security;
create or replace function public.angelcare_marketplace_footer_audit_trigger() returns trigger language plpgsql security definer set search_path=public as $$
declare v_actor text;v_object_id text;
begin
v_actor:=coalesce(case when tg_op='DELETE' then old.updated_by else new.updated_by end,'system');
v_object_id:=coalesce(case when tg_op='DELETE' then old.id::text else new.id::text end,null);
if tg_op='DELETE' then return old;end if;return new;
end;$$;
revoke all on function public.angelcare_marketplace_footer_audit_trigger() from public;
grant execute on function public.angelcare_marketplace_footer_audit_trigger() to service_role;
do $$ declare v_table text;begin foreach v_table in array array['angelcare_marketplace_footer_themes','angelcare_marketplace_footer_profiles','angelcare_marketplace_footer_sections','angelcare_marketplace_footer_links','angelcare_marketplace_footer_contact_desks','angelcare_marketplace_footer_targeting_rules','angelcare_marketplace_footer_schedules'] loop execute format('drop trigger if exists %I on public.%I','audit_'||v_table,v_table);execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.angelcare_marketplace_footer_audit_trigger()','audit_'||v_table,v_table);end loop;end $$;
update public.angelcare_marketplace_footer_profiles set is_default=false,updated_at=now() where profile_key<>'global-marketplace' and is_default=true;
create or replace function public.angelcare_marketplace_footer_snapshot(p_profile_id uuid) returns jsonb language sql security definer set search_path=public as $$
select jsonb_build_object('profile',to_jsonb(p),'theme',to_jsonb(t),'sections',coalesce((select jsonb_agg(to_jsonb(s) || jsonb_build_object('links',coalesce((select jsonb_agg(to_jsonb(l) order by l.sort_order) from public.angelcare_marketplace_footer_links l where l.section_id=s.id),'[]'::jsonb)) order by s.sort_order) from public.angelcare_marketplace_footer_sections s where s.profile_id=p.id),'[]'::jsonb)) from public.angelcare_marketplace_footer_profiles p left join public.angelcare_marketplace_footer_themes t on t.id=p.theme_id where p.id=p_profile_id;
$$;
create or replace function public.angelcare_marketplace_publish_footer_profile(p_profile_id uuid,p_actor_id text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_snapshot jsonb;v_version integer;v_version_id uuid;v_profile jsonb;
begin
select coalesce(max(version_number),0)+1 into v_version from public.angelcare_marketplace_footer_profile_versions where profile_id=p_profile_id;
v_snapshot:=public.angelcare_marketplace_footer_snapshot(p_profile_id);
if v_snapshot is null then raise exception 'Footer profile not found';end if;
update public.angelcare_marketplace_footer_profiles set status='published',version_number=v_version,published_at=now(),updated_at=now(),updated_by=p_actor_id where id=p_profile_id;
select to_jsonb(p) into v_profile from public.angelcare_marketplace_footer_profiles p where p.id=p_profile_id;
return jsonb_build_object('record',v_profile,'versionId',v_version_id,'versionNumber',v_version);
end;$$;
create or replace function public.angelcare_marketplace_duplicate_footer_profile(p_profile_id uuid,p_actor_id text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_source public.angelcare_marketplace_footer_profiles%rowtype;v_new_id uuid;v_key text;v_section record;v_new_section uuid;v_profile jsonb;
begin select * into v_source from public.angelcare_marketplace_footer_profiles where id=p_profile_id;if not found then raise exception 'Footer profile not found';end if;
v_key:=v_source.profile_key||'-copy-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISS');
for v_section in select * from public.angelcare_marketplace_footer_sections where profile_id=p_profile_id order by sort_order loop insert into public.angelcare_marketplace_footer_sections(profile_id,section_key,kind,title,description,eyebrow,icon_key,settings,targeting,contact_desk_keys,status,sort_order,column_span,mobile_default_open,locked,created_by,updated_by) values(v_new_id,v_section.section_key,v_section.kind,v_section.title,v_section.description,v_section.eyebrow,v_section.icon_key,v_section.settings,v_section.targeting,v_section.contact_desk_keys,v_section.status,v_section.sort_order,v_section.column_span,v_section.mobile_default_open,v_section.locked,p_actor_id,p_actor_id) returning id into v_new_section;insert into public.angelcare_marketplace_footer_links(section_id,link_key,label,href,link_type,open_new_tab,rel,visibility,analytics_key,status,sort_order,created_by,updated_by) select v_new_section,link_key,label,href,link_type,open_new_tab,rel,visibility,analytics_key,status,sort_order,p_actor_id,p_actor_id from public.angelcare_marketplace_footer_links where section_id=v_section.id;end loop;
select to_jsonb(p) into v_profile from public.angelcare_marketplace_footer_profiles p where p.id=v_new_id;return jsonb_build_object('record',v_profile);
end;$$;
create or replace function public.angelcare_marketplace_restore_footer_profile(p_profile_id uuid,p_version_id uuid,p_actor_id text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_snapshot jsonb;v_profile jsonb;v_sec jsonb;v_link jsonb;v_section_id uuid;
begin
select snapshot into v_snapshot from public.angelcare_marketplace_footer_profile_versions where id=p_version_id and profile_id=p_profile_id;
if v_snapshot is null then raise exception 'Footer version not found';end if;
update public.angelcare_marketplace_footer_profiles p set name=v_snapshot#>'{profile,name}',description=v_snapshot#>'{profile,description}',theme_id=nullif(v_snapshot#>>'{profile,theme_id}','')::uuid,settings=v_snapshot#>'{profile,settings}',brand=v_snapshot#>'{profile,brand}',authority_statement=v_snapshot#>>'{profile,authority_statement}',status='published',version_number=version_number+1,published_at=now(),updated_at=now(),updated_by=p_actor_id where p.id=p_profile_id;
update public.angelcare_marketplace_footer_sections set status='archived',updated_at=now(),updated_by=p_actor_id where profile_id=p_profile_id and section_key not in (select value->>'section_key' from jsonb_array_elements(coalesce(v_snapshot->'sections','[]'::jsonb)));
for v_sec in select value from jsonb_array_elements(coalesce(v_snapshot->'sections','[]'::jsonb)) loop
  values(p_profile_id,v_sec->>'section_key',coalesce(v_sec->>'kind','directory'),coalesce(v_sec->'title','{}'::jsonb),coalesce(v_sec->'description','{}'::jsonb),coalesce(v_sec->'eyebrow','{}'::jsonb),nullif(v_sec->>'icon_key',''),coalesce(v_sec->'settings','{}'::jsonb),coalesce(v_sec->'targeting','{}'::jsonb),coalesce(array(select jsonb_array_elements_text(coalesce(v_sec->'contact_desk_keys','[]'::jsonb))),'{}'::text[]),coalesce(v_sec->>'status','active'),coalesce((v_sec->>'sort_order')::integer,10),coalesce((v_sec->>'column_span')::integer,1),coalesce((v_sec->>'mobile_default_open')::boolean,false),coalesce((v_sec->>'locked')::boolean,false),p_actor_id)
  on conflict(profile_id,section_key) do update set kind=excluded.kind,title=excluded.title,description=excluded.description,eyebrow=excluded.eyebrow,icon_key=excluded.icon_key,settings=excluded.settings,targeting=excluded.targeting,contact_desk_keys=excluded.contact_desk_keys,status=excluded.status,sort_order=excluded.sort_order,column_span=excluded.column_span,mobile_default_open=excluded.mobile_default_open,locked=excluded.locked,updated_by=p_actor_id,updated_at=now()
  returning id into v_section_id;
  update public.angelcare_marketplace_footer_links set status='archived',updated_at=now(),updated_by=p_actor_id where section_id=v_section_id and link_key not in (select value->>'link_key' from jsonb_array_elements(coalesce(v_sec->'links','[]'::jsonb)));
  for v_link in select value from jsonb_array_elements(coalesce(v_sec->'links','[]'::jsonb)) loop
    values(v_section_id,v_link->>'link_key',coalesce(v_link->'label','{}'::jsonb),v_link->>'href',coalesce(v_link->>'link_type','internal'),coalesce((v_link->>'open_new_tab')::boolean,false),coalesce(array(select jsonb_array_elements_text(coalesce(v_link->'rel','[]'::jsonb))),'{}'::text[]),coalesce(v_link->'visibility','{}'::jsonb),nullif(v_link->>'analytics_key',''),coalesce(v_link->>'status','active'),coalesce((v_link->>'sort_order')::integer,10),p_actor_id)
    on conflict(section_id,link_key) do update set label=excluded.label,href=excluded.href,link_type=excluded.link_type,open_new_tab=excluded.open_new_tab,rel=excluded.rel,visibility=excluded.visibility,analytics_key=excluded.analytics_key,status=excluded.status,sort_order=excluded.sort_order,updated_by=p_actor_id,updated_at=now();
  end loop;
end loop;
select to_jsonb(p) into v_profile from public.angelcare_marketplace_footer_profiles p where p.id=p_profile_id;
return jsonb_build_object('record',v_profile);
end;$$;
revoke all on function public.angelcare_marketplace_footer_snapshot(uuid) from public;
revoke all on function public.angelcare_marketplace_publish_footer_profile(uuid,text) from public;
revoke all on function public.angelcare_marketplace_duplicate_footer_profile(uuid,text) from public;
revoke all on function public.angelcare_marketplace_restore_footer_profile(uuid,uuid,text) from public;
grant execute on function public.angelcare_marketplace_footer_snapshot(uuid) to service_role;
grant execute on function public.angelcare_marketplace_publish_footer_profile(uuid,text) to service_role;
grant execute on function public.angelcare_marketplace_duplicate_footer_profile(uuid,text) to service_role;
grant execute on function public.angelcare_marketplace_restore_footer_profile(uuid,uuid,text) to service_role;
commit;
select 'footer_command_studio_applied' as result,(select count(*) from public.angelcare_marketplace_footer_themes where status='active') as premium_themes,(select count(*) from public.angelcare_marketplace_footer_capabilities where status='active') as governed_capabilities,(select count(*) from public.angelcare_marketplace_footer_component_definitions where status='active') as governed_components,(select count(*) from public.angelcare_marketplace_footer_contact_desks where status='active') as professional_desks,(select count(*) from public.angelcare_marketplace_footer_profiles where status='published') as published_profiles;
